/** Independent native interval,reference,alignment and full base-count audit of original IGV output. */
final class IgvAudit {
    private IgvAudit() { }
    static Map<String,Object> verify(Model model,Path directory)throws Exception {
        model.verify();Path ledger=directory.resolve("original-igv.json");require(Files.size(ledger)<=268435456,"Original IGV ledger exceeds256MiB");Map<?,?> original=object(SimpleJson.parse(Files.readString(ledger,StandardCharsets.UTF_8)));
        equal(original.get("status"),"original-execution-completed-requires-native-audit","original completion");equal(original.get("igv_version"),"2.19.8","original version");equal(original.get("igv_build"),"14 (14)","original build");equal(original.get("frame_showing"),false,"hidden frame");equal(original.get("frame_width"),model.width(),"frame width");equal(original.get("frame_height"),model.height(),"frame height");equal(original.get("network_attempts_blocked"),List.of(),"local network guard");equal(original.get("reference_dictionary"),model.dictionary(),"complete reference dictionary");
        List<?> sequence=list(original.get("sequence_tracks"));require(sequence.size()==1,"Require one original sequence track");equal(object(sequence.get(0)).get("visible"),model.sequence(),"sequence visibility");preferences(model,object(original.get("actual_preferences")));
        List<?> actualViews=list(original.get("views"));require(actualViews.size()==model.views().size(),"Original view count differs");var proofs=new ArrayList<Map<String,Object>>();
        try(var reference=new IndexedFastaSequenceFile(model.reference())) {
            for(int vi=0;vi<actualViews.size();vi++) {
                View view=model.views().get(vi);Map<?,?> actual=object(actualViews.get(vi));equal(actual.get("id"),view.id(),"view identity");equal(actual.get("contig"),view.contig(),"view contig");coordinate(actual.get("start"),view.start());coordinate(actual.get("end"),view.end());double scale=number(actual.get("scale")),width=number(actual.get("width"));require(width>=1&&Math.abs(scale*width-(view.end()-view.start()))<=8*Math.ulp((double)view.end()),"Original pixel geometry differs from the requested interval");
                MessageDigest digest=MessageDigest.getInstance("SHA-256");for(int start=view.start();start<view.end();){int end=Math.min(view.end(),start+1048576);digest.update(reference.getSubsequenceAt(view.contig(),start+1L,end).getBases());start=end;}equal(actual.get("reference_sequence_sha256"),HexFormat.of().formatHex(digest.digest()),"full original reference sequence");
                var trackProofs=new ArrayList<Map<String,Object>>();List<?> found=list(actual.get("tracks"));int expectedTracks=0;
                for(Track track:model.tracks()) {
                    List<Map<?,?>> matches=new ArrayList<>();for(Object item:found){Map<?,?> row=object(item);if(track.id().equals(row.get("track_id")))matches.add(row);}int expected=track.kind().equals("bam")?3:track.kind().equals("seg")?(int)track.segments().stream().map(Seg::sample).distinct().count():1;require(matches.size()==expected,"Missing/extra original track:"+track.id());expectedTracks+=expected;var samples=new HashSet<String>();var roles=new HashSet<String>();
                    for(Map<?,?> row:matches) {
                        String role=String.valueOf(row.get("role")),sample=String.valueOf(row.get("sample"));require(samples.add(sample)||track.kind().equals("bam"),"Duplicate original SEG sample");require(roles.add(role)||track.kind().equals("seg"),"Duplicate original track role");equal(row.get("color"),track.color(),"positive color");equal(row.get("negative_color"),track.negativeColor(),"negative color");equal(row.get("auto_scale"),false,"explicit scaling");equal(row.get("display"),track.display().toUpperCase(Locale.ROOT),"requested display mode");equal(row.get("visible"),!role.equals("junction")||model.reads().junctions(),"track visibility");require(number(row.get("height"))>=0&&(!Boolean.TRUE.equals(row.get("visible"))||number(row.get("height"))>0),"Original visible track has no positive height");
                        var proof=new LinkedHashMap<String,Object>();proof.put("track_id",track.id());proof.put("kind",track.kind());proof.put("role",role);proof.put("sample",sample);proof.put("actual_height",row.get("height"));
                        if(!track.range().isEmpty()&&!role.equals("alignment")&&!role.equals("junction"))equal(row.get("range"),List.of((double)track.range().get(0).floatValue(),0.0,(double)track.range().get(1).floatValue()),"declared float32 range");
                        switch(track.kind()) {
                            case "bed6" -> {equal(role,"feature","BED role");var expectedFeatures=new ArrayList<Map<String,Object>>();for(Feature f:track.features())if(f.contig().equals(view.contig())&&f.end()>=view.start()&&f.start()<=view.end())expectedFeatures.add(Map.of("contig",f.contig(),"start",f.start(),"end",f.end(),"name",f.name(),"score",f.score(),"strand",f.strand().equals(".")?"":f.strand()));multiset(expectedFeatures,list(row.get("features")),"complete original BED geometry/name/score/strand;original inclusive boundary lookup");proof.put("features_compared",expectedFeatures.size());}
                            case "bedgraph","bigwig","seg" -> {
                                equal(role,"signal","numeric role");List<Segment> values=track.signal();if(track.kind().equals("seg")){require(samples.contains(sample)&&track.segments().stream().anyMatch(s->s.sample().equals(sample)),"Unknown original SEG sample");values=track.segments().stream().filter(s->s.sample().equals(sample)).map(s->new Segment(s.contig(),s.start(),s.end(),s.value())).toList();palette(track,row);equal(row.get("rendered_score_at_0_1_2"),List.of(0,1,2),"raw SEG values must bypass original copy-number log heuristic");equal(row.get("track_type"),"OTHER","explicit raw SEG type");}else equal(row.get("window"),"none","raw values without zoom/statistical reduction");
                                Path returned=member(directory,row.get("signal_file"));var observed=new ArrayList<Segment>();try(var lines=Files.newBufferedReader(returned,StandardCharsets.US_ASCII)){equal(lines.readLine(),"start\tend\tvalue","original signal header");String line;while((line=lines.readLine())!=null){require(observed.size()<model.maximumRecords(),"Excessive original signal count");String[] f=line.split("\t",-1);require(f.length==3,"Invalid original signal row");int start=Integer.parseInt(f[0]),end=Integer.parseInt(f[1]);float value=Float.parseFloat(f[2]);require(Float.isFinite(value),"Nonfinite original scalar");observed.add(new Segment(view.contig(),start,end,value));}}equal(row.get("returned_signal_intervals"),observed.size(),"original signal ledger count");proof.putAll(signal(values,observed,view));proof.put("original_signal_sha256",hash(returned));
                            }
                            case "bam" -> {require(Set.of("coverage","junction","alignment").contains(role),"Unexpected original BAM role");if(role.equals("alignment")){equal(row.get("view_pairs"),model.reads().pairs(),"view pairs");equal(row.get("color_by"),model.reads().colorBy().equals("strand")?"READ_STRAND":"NONE","alignment color policy");proof.putAll(alignments(model,track,view,row,directory));}}
                            default -> throw new IOException("Unadmitted track kind");
                        }
                        trackProofs.add(proof);
                    }
                }
                require(found.size()==expectedTracks,"Original ledger contains unrequested tracks");var proof=new LinkedHashMap<String,Object>();proof.put("view_id",view.id());proof.put("contig",view.contig());proof.put("start_zero_based",view.start());proof.put("end_exclusive",view.end());proof.put("reference_bases_compared",view.end()-view.start());proof.put("coordinate_tolerance","8ULPs of the requested endpoint;scalar/count tolerance0");proof.put("tracks",trackProofs);proof.put("png",image(directory.resolve(view.id()+".png"),model));proof.put("session",session(directory.resolve(view.id()+".session.xml"),model,view));proofs.add(proof);
            }
        }
        model.verify();return Map.of("status","passed-native-complete-value-audit","original_ledger_sha256",hash(ledger),"views",proofs,"interpretation","Exact scalar/missing functions,BED identity,reference bases,selected BAM identities/raw tags and all per-base counts;figures remain manual visual evidence,not variant calls,allele-specific inference or methylation interpretation.");
    }
    private static void preferences(Model model,Map<?,?> prefs)throws IOException {
        var expected=new LinkedHashMap<String,String>();expected.put("PORT_ENABLED","false");expected.put("AUTOSAVES_TO_KEEP","0");expected.put("PROVISIONING_URL_DEFAULT","");expected.put("SAM.DOWNSAMPLE_READS","false");Reads r=model.reads();if(r!=null){expected.put("SAM.QUALITY_THRESHOLD",String.valueOf(r.minimumMapq()));expected.put("SAM.FILTER_DUPLICATES",String.valueOf(!r.duplicates()));expected.put("SAM.FILTER_FAILED_READS",String.valueOf(!r.failed()));expected.put("SAM.FILTER_SECONDARY_ALIGNMENTS",String.valueOf(!r.secondary()));expected.put("SAM.FILTER_SUPPLEMENTARY_ALIGNMENTS",String.valueOf(!r.supplementary()));expected.put("SAM.SHOW_SOFT_CLIPPED",String.valueOf(r.softClips()));expected.put("SAM.SHOW_JUNCTION_TRACK",String.valueOf(r.junctions()));expected.put("SAM.COUNT_DELETED_BASES_COVERED",String.valueOf(r.deletionsInCoverage()));expected.put("SAM.SHOW_ALL_BASES",String.valueOf(r.colorBy().equals("base")));}for(var e:expected.entrySet())equal(prefs.get(e.getKey()),e.getValue(),"actual original preference:"+e.getKey());
    }
    private static void palette(Track track,Map<?,?> row)throws IOException {
        var expected=Map.of("minimum",(double)track.range().get(0).floatValue(),"maximum",(double)track.range().get(1).floatValue(),"negative_start",0,"positive_start",0,"minimum_color",track.negativeColor(),"middle_color",List.of(255,255,255),"maximum_color",track.color(),"double_gradient",true);equal(row.get("palette"),expected,"exact original SEG palette parameters");
    }
    static Map<String,Object> signal(List<Segment> expected,List<Segment> actual,View view)throws IOException {
        List<Segment> wanted=normalize(expected,view),found=normalize(actual,view);require(wanted.size()==found.size(),"Original signal/missing function has different interval geometry");long covered=0;for(int i=0;i<wanted.size();i++){Segment a=wanted.get(i),b=found.get(i);require(a.start()==b.start()&&a.end()==b.end()&&Float.floatToIntBits((float)a.value())==Float.floatToIntBits((float)b.value()),"Original signal/missing function differs at interval"+i+":"+a+" versus"+b);covered+=a.end()-a.start();}return Map.of("query_bases",view.end()-view.start(),"represented_bases_compared",covered,"missing_bases_compared",view.end()-view.start()-covered,"canonical_runs_compared",wanted.size(),"original_returned_intervals",actual.size(),"scalar_tolerance",0,"comparison","Exact float32 piecewise function;adjacent equal-valued subdivisions are equivalent;missing differs from measured0");
    }
    private static List<Segment> normalize(List<Segment> input,View view)throws IOException {
        var clipped=new ArrayList<Segment>();for(Segment s:input)if(s.chromosome().equals(view.contig())&&s.end()>view.start()&&s.start()<view.end())clipped.add(new Segment(s.chromosome(),Math.max(view.start(),s.start()),Math.min(view.end(),s.end()),s.value()));clipped.sort(Comparator.comparingLong(Segment::start).thenComparingLong(Segment::end));var unique=new ArrayList<Segment>();for(Segment s:clipped){if(!unique.isEmpty()){Segment p=unique.get(unique.size()-1);if(p.start()==s.start()&&p.end()==s.end()&&Float.floatToIntBits((float)p.value())==Float.floatToIntBits((float)s.value()))continue;require(p.end()<=s.start(),"Overlapping original/native scalar intervals with different bounds or values");}unique.add(s);}var result=new ArrayList<Segment>();for(Segment s:unique){if(!result.isEmpty()){Segment p=result.get(result.size()-1);if(p.end()==s.start()&&Float.floatToIntBits((float)p.value())==Float.floatToIntBits((float)s.value())){result.set(result.size()-1,new Segment(p.chromosome(),p.start(),s.end(),p.value()));continue;}}result.add(s);}return result;
    }
    private static Map<String,Object> alignments(Model model,Track track,View view,Map<?,?> row,Path directory)throws Exception {
        var expected=new ArrayList<Map<String,Object>>();int[][] counts=new int[view.end()-view.start()][10];Reads policy=model.reads();
        try(var reader=SamReaderFactory.makeDefault().validationStringency(ValidationStringency.STRICT).enable(SamReaderFactory.Option.DONT_MEMORY_MAP_INDEX).open(SamInputResource.of(track.file()).index(track.index()));var query=reader.query(view.contig(),view.start()+1,view.end(),false)) {
            int scanned=0;while(query.hasNext()) {SAMRecord read=query.next();require(++scanned<=model.maximumRecords(),"Native BAM query exceeds record bound including excluded reads");if(read.getReadUnmappedFlag()||read.getMappingQuality()<policy.minimumMapq()||!policy.duplicates()&&read.getDuplicateReadFlag()||!policy.failed()&&read.getReadFailsVendorQualityCheckFlag()||!policy.secondary()&&read.isSecondaryAlignment()||!policy.supplementary()&&read.getSupplementaryAlignmentFlag())continue;
                var r=new LinkedHashMap<String,Object>();r.put("name",read.getReadName());r.put("start",read.getAlignmentStart()-1);r.put("end",read.getAlignmentEnd());r.put("sequence",read.getReadString());r.put("cigar",read.getCigarString());r.put("mapq",read.getMappingQuality());r.put("negative",read.getReadNegativeStrandFlag());r.put("paired",read.getReadPairedFlag());r.put("first",read.getReadPairedFlag()&&read.getFirstOfPairFlag());r.put("second",read.getReadPairedFlag()&&read.getSecondOfPairFlag());r.put("duplicate",read.getDuplicateReadFlag());r.put("secondary",read.isSecondaryAlignment());r.put("supplementary",read.getSupplementaryAlignmentFlag());r.put("failed",read.getReadFailsVendorQualityCheckFlag());for(String tag:List.of("MM","Mm","ML","Ml","MN","SA","HP","PS")){Object value=read.getAttribute(tag);if(value instanceof byte[] bytes)r.put(tag,Base64.getEncoder().encodeToString(bytes));else if(value!=null)r.put(tag,value);}expected.add(r);count(read,view,counts,policy);
            }
        }
        multiset(expected,list(row.get("alignments")),"selected original read geometry/CIGAR/sequence/MAPQ/flags/raw modification and phase tags");Path file=member(directory,row.get("counts_file"));Path nativeFile=directory.resolve(view.id()+"-"+track.id()+"-native-counts.tsv");String header="position\ttotal\tpositive\tnegative\tA\tC\tG\tT\tN\tdeletion\tinsertion";
        try(var in=Files.newBufferedReader(file,StandardCharsets.US_ASCII);var out=Files.newBufferedWriter(nativeFile,StandardCharsets.US_ASCII)){equal(in.readLine(),header,"base-count header");out.write(header+"\n");for(int i=0;i<counts.length;i++){String line=in.readLine();require(line!=null,"Truncated original per-base counts");String[] f=line.split("\t",-1);require(f.length==11&&Integer.parseInt(f[0])==view.start()+i,"Original base-count geometry differs");out.write(Integer.toString(view.start()+i));for(int j=0;j<10;j++){int observed=Integer.parseInt(f[j+1]);require(observed==counts[i][j],"Original base-count mismatch at"+(view.start()+i)+",column"+(j+1)+":expected"+counts[i][j]+",found"+observed);out.write("\t"+counts[i][j]);}out.write('\n');}require(in.readLine()==null,"Extra original per-base rows");}
        return Map.of("selected_alignments_compared",expected.size(),"base_positions_compared",counts.length,"integer_counts_compared",10L*counts.length,"count_tolerance",0,"original_counts_sha256",hash(file),"native_counts_sha256",hash(nativeFile),"count_policy","Each selected alignment independently;all base qualities;softclips excluded from coverage;insertions counted as CIGAR events at current reference cursor;N skipped;D included in totals only under explicit policy;no inferred allelic/methylation analysis");
    }
    private static void count(SAMRecord read,View view,int[][] counts,Reads policy)throws IOException {
        byte[] bases=read.getReadBases();int reference=read.getAlignmentStart()-1,offset=0;for(CigarElement element:read.getCigar().getCigarElements()){int n=element.getLength();CigarOperator op=element.getOperator();if(op==CigarOperator.M||op==CigarOperator.EQ||op==CigarOperator.X){require(offset+n<=bases.length,"BAM CIGAR exceeds sequence");for(int k=Math.max(0,view.start()-reference);k<Math.min(n,view.end()-reference);k++){int[] row=counts[reference+k-view.start()];row[0]=Math.incrementExact(row[0]);int strand=read.getReadNegativeStrandFlag()?2:1;row[strand]=Math.incrementExact(row[strand]);int base=switch(Character.toUpperCase((char)bases[offset+k])){case 'A'->3;case 'C'->4;case 'G'->5;case 'T'->6;case 'N'->7;default->-1;};if(base>=0)row[base]=Math.incrementExact(row[base]);}}
            else if(op==CigarOperator.D){for(int pos=Math.max(reference,view.start());pos<Math.min(reference+n,view.end());pos++){int[] row=counts[pos-view.start()];row[8]=Math.incrementExact(row[8]);if(policy.deletionsInCoverage()){row[0]=Math.incrementExact(row[0]);int strand=read.getReadNegativeStrandFlag()?2:1;row[strand]=Math.incrementExact(row[strand]);}}}
            else if(op==CigarOperator.I&&reference>=view.start()&&reference<view.end()){int[] row=counts[reference-view.start()];row[9]=Math.incrementExact(row[9]);}if(op.consumesReadBases())offset=Math.addExact(offset,n);if(op.consumesReferenceBases())reference=Math.addExact(reference,n);
        }require(offset==bases.length&&reference==read.getAlignmentEnd(),"BAM CIGAR/reference/read length mismatch");
    }
    private static Map<String,Object> image(Path file,Model model)throws Exception {
        require(Files.isRegularFile(file)&&Files.size(file)>100,"Missing/truncated original PNG");try(var input=ImageIO.createImageInputStream(file.toFile())){var readers=ImageIO.getImageReaders(input);require(readers.hasNext(),"Unreadable original image");var reader=readers.next();try{reader.setInput(input);require(reader.getFormatName().equalsIgnoreCase("png"),"Original image is not PNG");int width=reader.getWidth(0),height=reader.getHeight(0);require(width>0&&width<=model.width()+32&&height>0&&height<=3*model.height()+1000,"Original PNG dimensions exceed bounded panel geometry");return Map.of("file",file.getFileName().toString(),"width",width,"height",height,"sha256",hash(file),"pixels","Original IGV output retained unmodified;labels and units in FIGURE_LEGEND.md");}finally{reader.dispose();}}
    }
    private static Map<String,Object> session(Path file,Model model,View view)throws Exception {
        require(Files.isRegularFile(file)&&Files.size(file)<=16777216,"Missing/oversized original session");var factory=DocumentBuilderFactory.newInstance();factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");var document=factory.newDocumentBuilder().parse(file.toFile());var root=document.getDocumentElement();equal(root.getTagName(),"Session","original session root");equal(portable(file,root.getAttribute("genome")).toString(),model.reference().toString(),"portable session reference");equal(root.getAttribute("locus"),view.contig()+":"+view.start()+"-"+view.end(),"original session zero-based locus");var resources=document.getElementsByTagName("Resource");var expected=new TreeSet<String>();for(Track track:model.tracks())expected.add(track.file().toString());var actual=new TreeSet<String>();for(int i=0;i<resources.getLength();i++){var resource=(org.w3c.dom.Element)resources.item(i);require(!resource.hasAttribute("index"),"Original session must discover the explicit staged adjacent index without a stale absolute override");actual.add(portable(file,resource.getAttribute("path")).toString());}equal(actual,expected,"complete portable original session resources");return Map.of("file",file.getFileName().toString(),"sha256",hash(file),"resources",actual.size(),"locus",root.getAttribute("locus"));
    }
    private static Path portable(Path session,String value)throws IOException {Path relative=Path.of(value);require(!relative.isAbsolute()&&!value.contains(":")&&relative.startsWith("inputs"),"Original session contains nonportable/outside data path");Path resolved=session.getParent().resolve(relative).normalize();require(resolved.startsWith(session.getParent().resolve("inputs"))&&Files.isRegularFile(resolved),"Portable session resource missing");return resolved;}
    private static Path member(Path directory,Object name)throws IOException {require(name instanceof String&&((String)name).matches("[A-Za-z][A-Za-z0-9_-]*\\.tsv"),"Unsafe original ledger member");Path file=directory.resolve((String)name);require(Files.isRegularFile(file)&&Files.size(file)<=268435456,"Missing/oversized original ledger member");return file;}
    private static void coordinate(Object value,int requested)throws IOException {require(Math.abs(number(value)-requested)<=8*Math.ulp((double)requested),"Original frame coordinate differs from requested half-open endpoint");}
    private static void multiset(List<?> expected,List<?> actual,String what)throws IOException {var a=new ArrayList<String>();for(Object v:expected)a.add(canonical(v));var b=new ArrayList<String>();for(Object v:actual)b.add(canonical(v));Collections.sort(a);Collections.sort(b);require(a.equals(b),"Original mismatch:"+what);}
    static void equal(Object actual,Object expected,String what)throws IOException {require(canonical(actual).equals(canonical(expected)),"Original mismatch:"+what+";expected"+canonical(expected)+";found"+canonical(actual));}
    private static String canonical(Object value)throws IOException {if(value instanceof Number n){double d=n.doubleValue();require(Double.isFinite(d),"Nonfinite ledger number");return Double.toHexString(d);}if(value instanceof Map<?,?> map){var sorted=new TreeMap<String,String>();for(var e:map.entrySet())sorted.put(String.valueOf(e.getKey()),canonical(e.getValue()));return sorted.toString();}if(value instanceof Collection<?> list){var entries=new ArrayList<String>();for(Object item:list)entries.add(canonical(item));return entries.toString();}return RegenieRuntime.json(value);}
}
